samples.gold:
-- migrate:up

CREATE TABLE document_types (
  id INTEGER PRIMARY KEY,
  name TEXT
);

CREATE TABLE industries (
  id INTEGER PRIMARY KEY,
  name TEXT
);

CREATE TABLE specialisms (
  id INTEGER PRIMARY KEY,
  name TEXT
);

CREATE TABLE carrere_grades (
  id INTEGER PRIMARY KEY,
  name TEXT
);

CREATE TABLE carreres (
  id INTEGER PRIMARY KEY,
  name TEXT,
  carrere_grade_id INTEGER,
  FOREIGN KEY (carrere_grade_id) REFERENCES carrere_grades(id)
);

CREATE TABLE program_types (
  id INTEGER PRIMARY KEY,
  name TEXT
);

CREATE TABLE dni_types (
  id INTEGER PRIMARY KEY,
  name TEXT
);

CREATE TABLE nations (
  id INTEGER PRIMARY KEY,
  name TEXT
);

CREATE TABLE periods (
  id INTEGER PRIMARY KEY,
  name TEXT,
  init_date TEXT,
  end_date TEXT
);

CREATE TABLE programs (
  id INTEGER PRIMARY KEY,
  name TEXT,
  description TEXT,
  image_url TEXT,
  pdf_url TEXT,
  max_participant_team INTEGER,
  created_at TEXT,
  updated_at TEXT,
  program_type_id INTEGER,
  period_id INTEGER,
  FOREIGN KEY (period_id) REFERENCES periods(id),
  FOREIGN KEY (program_type_id) REFERENCES program_types(id)
);

CREATE TABLE phases (
  id INTEGER PRIMARY KEY,
  name TEXT,
  description TEXT,
  init_date TEXT,
  end_date TEXT,
  delivery_deadline TEXT,
  evaluation_deadline TEXT,
  revaluation_deadline TEXT,
  created_at TEXT,
  updated_at TEXT,
  program_id INTEGER,
  FOREIGN KEY (program_id) REFERENCES programs(id)
);

CREATE TABLE participants (
  id INTEGER PRIMARY KEY,
  names TEXT,
  last_names TEXT,
  email TEXT,
  phone TEXT,
  dni TEXT,
  created_at TEXT,
  updated_at TEXT,
  dni_type_id INTEGER,
  nation_id INTEGER,
  user_id INTEGER,
  FOREIGN KEY (dni_type_id) REFERENCES dni_types(id),
  FOREIGN KEY (nation_id) REFERENCES nations(id)
);

CREATE TABLE internals (
  id INTEGER PRIMARY KEY,
  code INTEGER,
  participant_id INTEGER,
  period_id INTEGER,
  carrere_id INTEGER,
  FOREIGN KEY (carrere_id) REFERENCES carreres(id),
  FOREIGN KEY (period_id) REFERENCES periods(id)
);

CREATE TABLE externals (
  id INTEGER PRIMARY KEY,
  participant_id INTEGER
);

CREATE TABLE workers (
  id INTEGER PRIMARY KEY,
  names TEXT,
  last_names TEXT,
  email TEXT,
  phone TEXT,
  created_at TEXT,
  updated_at TEXT,
  user_id INTEGER
);

CREATE TABLE external_workers (
  id INTEGER PRIMARY KEY,
  worker_id INTEGER
);

CREATE TABLE internal_workers (
  id INTEGER PRIMARY KEY,
  worker_id INTEGER,
  code INTEGER
);

CREATE TABLE mentors (
  id INTEGER PRIMARY KEY,
  worker_id INTEGER
);

CREATE TABLE mentors_spcialisms (
  id INTEGER PRIMARY KEY,
  mentor_id INTEGER,
  specialism_id INTEGER,
  FOREIGN KEY (mentor_id) REFERENCES mentors(id),
  FOREIGN KEY (specialism_id) REFERENCES specialisms(id)
);

-- migrate:down

DROP TABLE IF EXISTS document_types;
DROP TABLE IF EXISTS industries;
DROP TABLE IF EXISTS specialisms;
DROP TABLE IF EXISTS carrere_grades;
DROP TABLE IF EXISTS carreres;
DROP TABLE IF EXISTS program_types;
DROP TABLE IF EXISTS dni_types;
DROP TABLE IF EXISTS nations;
DROP TABLE IF EXISTS periods;
DROP TABLE IF EXISTS programs;
DROP TABLE IF EXISTS phases;
DROP TABLE IF EXISTS participants;
DROP TABLE IF EXISTS internals;
DROP TABLE IF EXISTS externals;
DROP TABLE IF EXISTS workers;
DROP TABLE IF EXISTS external_workers;
DROP TABLE IF EXISTS internal_workers;
DROP TABLE IF EXISTS mentors;
DROP TABLE IF EXISTS mentors_spcialisms;
